script:
(function () {
  'use strict';

  var video = document.getElementById('cameraVideo');
  var previewWrap = document.getElementById('cameraPreviewWrap');
  var placeholder = document.getElementById('cameraPlaceholder');
  var deviceSelect = document.getElementById('deviceSelect');
  var btnDetect = document.getElementById('btnDetect');
  var btnStop = document.getElementById('btnStopCamera');
  var checkBruteForce = document.getElementById('checkBruteForce');
  var bruteLimit = document.getElementById('bruteLimit');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var progressWrap = document.getElementById('probeProgressWrap');
  var progressFill = document.getElementById('probeProgressFill');
  var ladderList = document.getElementById('ladderList');
  var statResolution = document.getElementById('statPeakResolution');
  var statMegapixels = document.getElementById('statPeakMegapixels');
  var statAspect = document.getElementById('statPeakAspect');
  var statStandard = document.getElementById('statPeakStandard');
  var statDefault = document.getElementById('statDefaultResolution');
  var statMin = document.getElementById('statMinResolution');
  var statCount = document.getElementById('statSupportedCount');
  var statMaxFps = document.getElementById('statMaxFps');
  var statFpsAtMax = document.getElementById('statFpsAtMax');
  var statCameraName = document.getElementById('statCameraName');
  var statBrowser = document.getElementById('statBrowser');
  var statNonStandard = document.getElementById('statNonStandard');
  var exportFormat = document.getElementById('exportFormat');
  var btnExport = document.getElementById('btnExport');
  var btnCopyResults = document.getElementById('btnCopyResults');

  // Standard video resolutions, 8K down to QQVGA, sorted by pixel area
  // descending. Kept as the single source the ladder display and the probe
  // loop both read from, so they can never disagree with each other.
  var STANDARDS = [
    ['8K UHD', 7680, 4320], ['5K', 5120, 2880], ['DCI 4K', 4096, 2160], ['4K UHD', 3840, 2160],
    ['8 MP (4:3)', 3264, 2448], ['5 MP (4:3)', 2592, 1944], ['QHD+', 2560, 1600], ['QHD', 2560, 1440],
    ['3 MP (16:9)', 2304, 1296], ['Full HD+', 1920, 1200], ['Full HD', 1920, 1080], ['UXGA', 1600, 1200],
    ['HD+', 1600, 900], ['SXGA', 1280, 1024], ['SXGA−', 1280, 960], ['WXGA', 1280, 800], ['HD', 1280, 720],
    ['XGA', 1024, 768], ['WSVGA', 1024, 600], ['SVGA', 800, 600], ['VGA', 640, 480], ['nHD', 640, 360],
    ['CIF', 352, 288], ['QVGA', 320, 240], ['QCIF', 176, 144], ['QQVGA', 160, 120],
  ].sort(function (a, b) { return (b[1] * b[2]) - (a[1] * a[2]); });

  var currentStream = null;
  var running = false;
  var scanToken = 0;
  var results = {};      // 'WxH' -> result row
  var defaultRes = null; // { width, height }
  var capsCache = null;
  var lastSummary = null;
  var bruteUsed = false;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  function gcd(a, b) { return b === 0 ? a : gcd(b, a % b); }
  function key(w, h) { return w + 'x' + h; }
  function mp(w, h) { return (w * h / 1e6).toFixed(2); }

  function aspectLabel(w, h) {
    var g = gcd(w, h) || 1;
    var aw = w / g, ah = h / g;
    if (aw <= 32) return aw + ':' + ah;
    var r = w / h, named = [[16, 9], [4, 3], [16, 10], [3, 2], [5, 4], [21, 9]];
    for (var i = 0; i < named.length; i++) if (Math.abs(r - named[i][0] / named[i][1]) < 0.02) return '≈' + named[i][0] + ':' + named[i][1];
    return r.toFixed(2) + ':1';
  }

  function standardName(w, h) {
    for (var i = 0; i < STANDARDS.length; i++) if (STANDARDS[i][1] === w && STANDARDS[i][2] === h) return STANDARDS[i][0];
    return null;
  }

  function closestStandard(w, h) {
    var best = null, bestDiff = Infinity;
    STANDARDS.forEach(function (s) {
      var diff = Math.abs(s[1] * s[2] - w * h);
      if (diff < bestDiff) { bestDiff = diff; best = s[0]; }
    });
    return standardName(w, h) || ('≈ ' + best);
  }

  function browserName() {
    var ua = navigator.userAgent || '', m;
    if ((m = /Edg\/(\d+)/.exec(ua))) return 'Edge ' + m[1];
    if ((m = /OPR\/(\d+)/.exec(ua))) return 'Opera ' + m[1];
    if ((m = /Firefox\/(\d+)/.exec(ua))) return 'Firefox ' + m[1];
    if ((m = /Chrome\/(\d+)/.exec(ua))) return 'Chrome ' + m[1];
    if ((m = /Version\/(\d+).*Safari/.exec(ua))) return 'Safari ' + m[1];
    return 'Unknown browser';
  }

  function setProgress(pct) {
    if (pct === null) { progressWrap.classList.add('u-hidden'); return; }
    progressWrap.classList.remove('u-hidden');
    progressFill.style.width = Math.round(pct) + '%';
  }

  function isSupported(r) { return r && (r.status === 'native' || r.status === 'scaled'); }

  function statusText(r) {
    if (!r) return '';
    var t = r.status === 'native' ? 'Supported' : r.status === 'scaled' ? 'Browser-scaled' : r.status === 'nearest' ? 'Gave ' + r.actualW + '×' + r.actualH : 'Not supported';
    if (r.fps && isSupported(r)) t += ' · ' + (Math.round(r.fps * 10) / 10) + ' fps';
    return t;
  }

  function renderLadder() {
    var rows = STANDARDS.map(function (s) { return { name: s[0], w: s[1], h: s[2] }; });
    Object.keys(results).forEach(function (k) {
      var r = results[k];
      if (!standardName(r.reqW, r.reqH)) rows.push({ name: r.name, w: r.reqW, h: r.reqH });
    });
    rows.sort(function (a, b) { return b.w * b.h - a.w * a.h; });
    var summary = lastSummary;
    ladderList.innerHTML = rows.map(function (row) {
      var k = key(row.w, row.h);
      var r = results[k];
      var cls = 'ladder-item';
      var tags = [];
      if (r) {
        if (isSupported(r)) cls += ' supported';
        else if (r.status === 'unsupported') cls += ' failed';
        if (summary && summary.max && summary.max.key === k) { cls += ' best'; tags.push('Maximum'); }
        if (summary && summary.min && summary.min.key === k) tags.push('Minimum');
      }
      if (defaultRes && defaultRes.width === row.w && defaultRes.height === row.h) tags.push('Default');
      return '<div class="' + cls + '"><span class="ladder-name">' + escapeHtml(row.name) + (tags.length ? ' <span class="chip chip-new">' + tags.join(' · ') + '</span>' : '') + '</span>' +
        '<span class="ladder-dims">' + row.w + '×' + row.h + ' · ' + mp(row.w, row.h) + ' MP</span><span>' + escapeHtml(statusText(r)) + '</span></div>';
    }).join('');
  }

  function resetStats() {
    [statResolution, statMegapixels, statAspect, statStandard, statDefault, statMin, statCount, statMaxFps, statFpsAtMax, statCameraName, statNonStandard].forEach(function (el) { el.textContent = '—'; });
    results = {};
    defaultRes = null;
    lastSummary = null;
    btnExport.disabled = true;
    btnCopyResults.disabled = true;
  }

  // Same stopStream() shape every camera tool on this site copies (see
  // webcam-test-online's own script and this project's CLAUDE.md).
  function stopStream() {
    scanToken++;
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    video.srcObject = null;
    previewWrap.classList.remove('is-active');
    placeholder.style.display = 'flex';
    btnStop.disabled = true;
    if (running) finishScan(true);
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Camera access was blocked.</strong> Allow access from your browser’s address-bar icon or site settings, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No camera was detected.</strong> Connect a webcam and reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your camera is already in use</strong> by another app or browser tab.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Camera access requires HTTPS.</strong>' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong probing the camera.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices, currentDeviceId) {
    var cams = devices.filter(function (d) { return d.kind === 'videoinput'; });
    deviceSelect.innerHTML = '';
    cams.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Camera ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = cams.length === 0;
  }

  function isOverconstrained(err) {
    return err && (err.name === 'OverconstrainedError' || err.name === 'ConstraintNotSatisfiedError');
  }

  function openStream(deviceId, extra) {
    var c = extra ? JSON.parse(JSON.stringify(extra)) : {};
    if (deviceId) c.deviceId = { exact: deviceId };
    return navigator.mediaDevices.getUserMedia({ video: Object.keys(c).length ? c : true, audio: false }).then(function (stream) {
      if (currentStream) currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = stream;
      video.srcObject = stream;
      placeholder.style.display = 'none';
      previewWrap.classList.add('is-active');
      btnStop.disabled = false;
      return video.play().catch(function () {}).then(function () { return stream.getVideoTracks()[0]; });
    });
  }

  // Applies one size to the live track (fast) and reads back what the
  // track really delivers. Browsers without applyConstraints() fall back to
  // re-opening the camera, releasing the previous stream first.
  function applySize(w, h, mode, native, deviceId) {
    var c = mode === 'exact' ? { width: { exact: w }, height: { exact: h } } : { width: { ideal: w }, height: { ideal: h } };
    var fpsMax = capsCache && capsCache.frameRate && capsCache.frameRate.max;
    c.frameRate = { ideal: fpsMax || 60 };
    var supportsResize = navigator.mediaDevices.getSupportedConstraints && navigator.mediaDevices.getSupportedConstraints().resizeMode;
    if (native && supportsResize) c.resizeMode = { exact: 'none' };
    var track = currentStream && currentStream.getVideoTracks()[0];
    var p;
    if (track && track.applyConstraints) {
      p = track.applyConstraints(c).then(function () { return track; });
    } else {
      if (currentStream) { currentStream.getTracks().forEach(function (t) { t.stop(); }); currentStream = null; }
      p = openStream(deviceId, c);
    }
    return p.then(function (t) {
      var s = t.getSettings ? t.getSettings() : {};
      var aw = s.width || video.videoWidth || 0, ah = s.height || video.videoHeight || 0;
      var match = (Math.abs(aw - w) <= 1 && Math.abs(ah - h) <= 1) || (Math.abs(aw - h) <= 1 && Math.abs(ah - w) <= 1);
      var status = match ? (s.resizeMode === 'crop-and-scale' ? 'scaled' : 'native') : (mode === 'exact' ? 'unsupported' : 'nearest');
      return { actualW: aw, actualH: ah, fps: s.frameRate || 0, status: status };
    }, function (err) {
      if (isOverconstrained(err)) return { actualW: 0, actualH: 0, fps: 0, status: 'unsupported' };
      throw err;
    });
  }

  function record(name, w, h, res) {
    var k = key(w, h);
    results[k] = { key: k, name: name, reqW: w, reqH: h, actualW: res.actualW, actualH: res.actualH, fps: res.fps, status: res.status };
    // An "ideal" request that came back at another size still proves the
    // camera delivers that other size -- record it as a discovered size.
    if (res.status === 'nearest' && res.actualW && res.actualH) {
      var k2 = key(res.actualW, res.actualH);
      if (!results[k2] || !isSupported(results[k2])) {
        results[k2] = { key: k2, name: standardName(res.actualW, res.actualH) || 'Discovered size', reqW: res.actualW, reqH: res.actualH, actualW: res.actualW, actualH: res.actualH, fps: res.fps, status: 'native' };
      }
    }
  }

  function summarise() {
    var all = Object.keys(results).map(function (k) { return results[k]; });
    var native = all.filter(function (r) { return r.status === 'native'; });
    var pool = native.length ? native : all.filter(isSupported);
    if (!pool.length) return null;
    pool.sort(function (a, b) { return b.reqW * b.reqH - a.reqW * a.reqH; });
    var maxFps = 0;
    pool.forEach(function (r) { if (r.fps > maxFps) maxFps = r.fps; });
    return { max: pool[0], min: pool[pool.length - 1], count: pool.length, scaledCount: all.filter(function (r) { return r.status === 'scaled'; }).length, maxFps: maxFps };
  }

  function showSummary() {
    var s = summarise();
    lastSummary = s;
    statDefault.textContent = defaultRes ? defaultRes.width + '×' + defaultRes.height : '—';
    if (!s) { renderLadder(); return; }
    var w = s.max.reqW, h = s.max.reqH;
    statResolution.textContent = w + '×' + h;
    statMegapixels.textContent = mp(w, h) + ' MP';
    statAspect.textContent = aspectLabel(w, h);
    statStandard.textContent = closestStandard(w, h);
    statMin.textContent = s.min.reqW + '×' + s.min.reqH;
    statCount.textContent = String(s.count) + (s.scaledCount && s.max.status === 'native' ? ' (+' + s.scaledCount + ' scaled)' : '');
    statMaxFps.textContent = s.maxFps ? (Math.round(s.maxFps * 10) / 10) + ' fps' : 'Not reported';
    statFpsAtMax.textContent = s.max.fps ? (Math.round(s.max.fps * 10) / 10) + ' fps' : 'Not reported';
    var nonStd = Object.keys(results).filter(function (k) { return isSupported(results[k]) && !standardName(results[k].reqW, results[k].reqH); }).length;
    statNonStandard.textContent = bruteUsed ? nonStd + ' found' : 'Skipped (brute force off)';
    btnExport.disabled = false;
    btnCopyResults.disabled = false;
    renderLadder();
  }

  function buildCandidates() {
    bruteUsed = checkBruteForce.checked;
    var list = STANDARDS.map(function (s) { return { name: s[0], w: s[1], h: s[2], mode: 'exact', native: false }; });
    if (checkBruteForce.checked) {
      var limit = Math.max(320, Math.min(7680, parseInt(bruteLimit.value, 10) || 2048));
      var seen = {};
      list.forEach(function (c) { seen[key(c.w, c.h)] = 1; });
      [[4, 3], [16, 9], [16, 10]].forEach(function (ratio) {
        for (var w = 160; w <= limit; w += 16) {
          var h = Math.round(w * ratio[1] / ratio[0] / 2) * 2;
          var k = key(w, h);
          if (seen[k]) continue;
          seen[k] = 1;
          list.push({ name: 'Non-standard ' + ratio[0] + ':' + ratio[1], w: w, h: h, mode: 'exact', native: true, brute: true });
        }
      });
    }
    return list;
  }

  function finishScan(cancelled) {
    running = false;
    btnDetect.disabled = false;
    setProgress(100);
    setTimeout(function () { setProgress(null); }, 400);
    showSummary();
    var s = lastSummary;
    if (!s) {
      setDiagnostic([{ sev: cancelled ? 'warn' : 'error', html: cancelled ? 'Scan stopped before any size was confirmed.' : 'Could not negotiate any standard resolution with this camera.' }]);
      return;
    }
    // Leave the preview running at the maximum size found.
    if (!cancelled && currentStream) {
      applySize(s.max.reqW, s.max.reqH, 'ideal', false).catch(function () {});
    }
    setDiagnostic([{ sev: 'ok', html: (cancelled ? '<strong>Scan cancelled</strong> — partial results below. ' : '') + '<strong>' + s.max.reqW + '×' + s.max.reqH + '</strong> is the highest resolution your browser could negotiate with this camera (default ' + (defaultRes ? defaultRes.width + '×' + defaultRes.height : 'unknown') + ', minimum ' + s.min.reqW + '×' + s.min.reqH + '). Your camera’s native sensor resolution — and what its own manufacturer app can reach — may be higher; browsers commonly cap out around 1080p or 4K regardless of the physical sensor.' + (s.scaledCount ? ' Sizes marked <em>Browser-scaled</em> were produced by resizing a larger native mode.' : '') }]);
  }

  function runProbe(deviceId) {
    if (running) return;
    running = true;
    var token = ++scanToken;
    btnDetect.disabled = true;
    resetStats();
    statBrowser.textContent = browserName();
    renderLadder();
    setProgress(0);
    setDiagnostic([{ sev: '', html: 'Opening the camera at its default size…' }]);

    if (currentStream) { currentStream.getTracks().forEach(function (t) { t.stop(); }); currentStream = null; }
    openStream(deviceId).then(function (track) {
      if (token !== scanToken) return;
      var s = track.getSettings ? track.getSettings() : {};
      defaultRes = { width: s.width || video.videoWidth, height: s.height || video.videoHeight };
      statCameraName.textContent = track.label || 'Camera';
      try { capsCache = track.getCapabilities ? track.getCapabilities() : null; } catch (e) { capsCache = null; }
      navigator.mediaDevices.enumerateDevices().then(function (devices) { populateDeviceSelect(devices, s.deviceId); }).catch(function () {});

      var candidates = buildCandidates();
      var i = 0;
      setDiagnostic([{ sev: '', html: 'Checking ' + candidates.length + ' sizes — the picture may flicker while it works…' }]);
      function next() {
        if (token !== scanToken) return;
        if (i >= candidates.length) { finishScan(false); return; }
        var c = candidates[i++];
        setProgress(i / candidates.length * 100);
        applySize(c.w, c.h, c.mode, c.native, deviceId).then(function (res) {
          if (token !== scanToken) return;
          if (!c.brute || res.status === 'native') record(c.name, c.w, c.h, res);
          if (i % 4 === 0 || !c.brute) showSummary();
          next();
        }).catch(function (err) {
          if (token !== scanToken) return;
          running = false;
          btnDetect.disabled = false;
          setProgress(null);
          setDiagnostic([describeError(err)]);
          stopStream();
        });
      }
      next();
    }).catch(function (err) {
      running = false;
      btnDetect.disabled = false;
      setProgress(null);
      setDiagnostic([describeError(err)]);
      stopStream();
    });
  }

  // ---------- Export ----------
  function exportRows() {
    return Object.keys(results).map(function (k) { return results[k]; })
      .sort(function (a, b) { return b.reqW * b.reqH - a.reqW * a.reqH; })
      .map(function (r) {
        return {
          standard: r.name, requested: r.reqW + 'x' + r.reqH, actual: r.actualW ? r.actualW + 'x' + r.actualH : '',
          megapixels: mp(r.reqW, r.reqH), maxFps: r.fps ? String(Math.round(r.fps * 10) / 10) : '',
          status: statusText(r).split(' · ')[0],
          isDefault: !!(defaultRes && defaultRes.width === r.reqW && defaultRes.height === r.reqH),
        };
      });
  }

  function exportMeta() {
    return {
      camera: statCameraName.textContent, browser: statBrowser.textContent, maximum: statResolution.textContent,
      defaultResolution: statDefault.textContent, minimum: statMin.textContent, supportedSizes: statCount.textContent,
      maxFps: statMaxFps.textContent, fpsAtMaximum: statFpsAtMax.textContent, scanned: new Date().toISOString(),
    };
  }

  function buildExport(fmt) {
    var rows = exportRows(), meta = exportMeta();
    var cols = ['standard', 'requested', 'actual', 'megapixels', 'maxFps', 'status', 'isDefault'];
    var headers = ['Standard', 'Requested', 'Actual', 'Megapixels', 'Max FPS', 'Status', 'Default'];
    if (fmt === 'json') return { text: JSON.stringify({ summary: meta, resolutions: rows }, null, 2), type: 'application/json', ext: 'json' };
    if (fmt === 'md') {
      var md = '# Webcam resolution scan\n\n' + Object.keys(meta).map(function (k) { return '- **' + k + '**: ' + meta[k]; }).join('\n') + '\n\n| ' + headers.join(' | ') + ' |\n|' + headers.map(function () { return '---'; }).join('|') + '|\n';
      md += rows.map(function (r) { return '| ' + cols.map(function (c) { return String(r[c]).replace(/\|/g, '/'); }).join(' | ') + ' |'; }).join('\n');
      return { text: md + '\n', type: 'text/markdown', ext: 'md' };
    }
    if (fmt === 'xml') {
      var x = function (v) { return String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); };
      var xml = '<?xml version="1.0" encoding="UTF-8"?>\n<resolutionScan>\n  <summary>\n' + Object.keys(meta).map(function (k) { return '    <' + k + '>' + x(meta[k]) + '</' + k + '>'; }).join('\n') + '\n  </summary>\n  <resolutions>\n';
      xml += rows.map(function (r) { return '    <resolution ' + cols.map(function (c) { return c + '="' + x(r[c]) + '"'; }).join(' ') + '/>'; }).join('\n');
      return { text: xml + '\n  </resolutions>\n</resolutionScan>\n', type: 'application/xml', ext: 'xml' };
    }
    var esc = function (v) { return '"' + String(v).replace(/"/g, '""') + '"'; };
    var csv = [headers.map(esc).join(',')].concat(rows.map(function (r) { return cols.map(function (c) { return esc(r[c]); }).join(','); }));
    return { text: csv.join('\n') + '\n', type: 'text/csv', ext: 'csv' };
  }

  btnExport.addEventListener('click', function () {
    var out = buildExport(exportFormat.value);
    var url = URL.createObjectURL(new Blob([out.text], { type: out.type }));
    var a = document.createElement('a');
    a.href = url;
    a.download = 'webcam-resolution-scan.' + out.ext;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
  });

  btnCopyResults.addEventListener('click', function () {
    var out = buildExport(exportFormat.value);
    (navigator.clipboard ? navigator.clipboard.writeText(out.text) : Promise.reject()).then(function () {
      btnCopyResults.textContent = 'Copied!';
      setTimeout(function () { btnCopyResults.textContent = 'Copy Results'; }, 1500);
    }).catch(function () {
      setDiagnostic([{ sev: 'warn', html: 'Your browser blocked clipboard access — use <strong>Export Results</strong> instead.' }]);
    });
  });

  btnDetect.addEventListener('click', function () { runProbe(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Camera stopped.' }]);
  });
  deviceSelect.addEventListener('change', function () {
    // Switching devices mid-result just clears the stale result rather
    // than auto-re-probing, since the probe is an intentionally heavier
    // action (several resolution requests in a row).
    stopStream();
    resetStats();
    renderLadder();
    setDiagnostic([{ sev: '', html: 'Click <strong>Detect Maximum Resolution</strong> to probe this camera.' }]);
  });

  window.addEventListener('pagehide', stopStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  statBrowser.textContent = browserName();
  renderLadder();

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support camera access.</strong>' }]);
    btnDetect.disabled = true;
  }
})();
